import { NextResponse, type NextRequest } from 'next/server';
import jwt from 'jsonwebtoken';

// Define the JWT payload type for better type safety
interface JWTPayload {
  userId: string;
  email: string;
  iat?: number;
  exp?: number;
  role?: string;
}

// Configuration interface for better type safety
interface MiddlewareConfig {
  jwtSecret: string;
  tokenCookieName: string;
  loginPath: string;
  publicPaths: string[];
  protectedApiPaths: string[];
  tokenExpiry: string;
}

// Default configuration
const defaultConfig: MiddlewareConfig = {
  jwtSecret: process.env.JWT_SECRET || 'your-secret-key-change-in-production',
  tokenCookieName: 'auth-token',
  loginPath: '/login',
  publicPaths: [
    '/login',
    '/register',
    '/api/auth/login',
    '/api/auth/register',
    '/api/auth/refresh',
    '/api/auth/logout',
    '/_next/static',
    '/_next/image',
    '/favicon.ico',
    '/sitemap.xml',
    '/robots.txt',
    '/manifest.json'
  ],
  protectedApiPaths: [
    '/api/user',
    '/api/dashboard',
    '/api/admin'
  ],
  tokenExpiry: '24h'
};

/**
 * Next.js JWT Authentication Middleware
 * 
 * This middleware checks for a valid JWT token in cookies and redirects
 * unauthenticated users to the login page. It follows Next.js best practices
 * for security, performance, and user experience.
 * 
 * Features:
 * - JWT token verification with comprehensive error handling
 * - Cookie-based authentication with secure settings
 * - Automatic redirection with original URL preservation
 * - Public path exclusions for authentication and static assets
 * - User information injection into request/response headers
 * - TypeScript type safety throughout
 * - Configurable settings for different environments
 */
export function middleware(request: NextRequest) {
  const config = defaultConfig;

  // Get the token from cookies using the latest Next.js cookies API
  const token = request.cookies.get(config.tokenCookieName)?.value;

  // Check if the current path is public (doesn't require authentication)
  const isPublicPath = config.publicPaths.some(path => 
    request.nextUrl.pathname.startsWith(path) || 
    request.nextUrl.pathname === path
  );

  // Allow access to public paths without authentication
  if (isPublicPath) {
    // If user is already authenticated and tries to access login/register,
    // redirect them to dashboard
    if (token && (request.nextUrl.pathname === '/login' || request.nextUrl.pathname === '/register')) {
      return NextResponse.redirect(new URL('/dashboard', request.url));
    }
    return NextResponse.next();
  }

  // If no token is found, redirect to login with redirect parameter
  if (!token) {
    const loginUrl = new URL(config.loginPath, request.url);
    // Add the original URL as a query parameter to redirect back after login
    loginUrl.searchParams.set('redirect', request.nextUrl.pathname);
    loginUrl.searchParams.set('reason', 'unauthenticated');
    return NextResponse.redirect(loginUrl);
  }

  try {
    // Verify the JWT token with comprehensive validation
    const decoded = jwt.verify(token, config.jwtSecret, {
      algorithms: ['HS256'],
      maxAge: config.tokenExpiry
    }) as JWTPayload;

    // Validate required token payload fields
    if (!decoded.userId || !decoded.email) {
      throw new Error('Invalid token payload: missing required fields');
    }

    // Check token expiration explicitly (jwt.verify does this, but we can add custom logic)
    if (decoded.exp && decoded.exp < Math.floor(Date.now() / 1000)) {
      throw new Error('Token has expired');
    }

    // Optional: Role-based access control for API routes
    const isProtectedApiPath = config.protectedApiPaths.some(path => 
      request.nextUrl.pathname.startsWith(path)
    );

    if (isProtectedApiPath && decoded.role !== 'admin') {
      return NextResponse.json(
        { success: false, message: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    // Add user information to request headers for downstream use
    // Clone the request headers and set new headers
    const requestHeaders = new Headers(request.headers);
    requestHeaders.set('x-user-id', decoded.userId);
    requestHeaders.set('x-user-email', decoded.email);
    if (decoded.role) {
      requestHeaders.set('x-user-role', decoded.role);
    }

    // Create response with modified request headers
    const response = NextResponse.next({
      request: {
        headers: requestHeaders,
      },
    });

    // Set response headers for client-side access
    response.headers.set('x-user-id', decoded.userId);
    response.headers.set('x-user-email', decoded.email);
    if (decoded.role) {
      response.headers.set('x-user-role', decoded.role);
    }

    // Add security headers
    response.headers.set('X-Content-Type-Options', 'nosniff');
    response.headers.set('X-Frame-Options', 'DENY');
    response.headers.set('X-XSS-Protection', '1; mode=block');

    return response;

  } catch (error) {
    // Handle specific JWT errors with appropriate logging and user feedback
    let errorType = 'unknown';
    let errorMessage = 'Authentication failed';

    if (error instanceof jwt.JsonWebTokenError) {
      errorType = 'invalid_token';
      errorMessage = 'Invalid authentication token';
      console.error('Invalid JWT token:', error.message);
    } else if (error instanceof jwt.TokenExpiredError) {
      errorType = 'token_expired';
      errorMessage = 'Session expired';
      console.error('JWT token expired:', error.message);
    } else if (error instanceof jwt.NotBeforeError) {
      errorType = 'token_not_active';
      errorMessage = 'Token not active yet';
      console.error('JWT token not active yet:', error.message);
    } else if (error instanceof Error) {
      errorType = 'validation_error';
      errorMessage = error.message;
      console.error('JWT validation error:', error.message);
    } else {
      console.error('Unknown JWT verification error:', error);
    }

    // For API routes, return JSON error response
    if (request.nextUrl.pathname.startsWith('/api/')) {
      return NextResponse.json(
        { 
          success: false, 
          message: errorMessage,
          error_type: errorType 
        },
        { status: 401 }
      );
    }

    // For page routes, redirect to login with error information
    const loginUrl = new URL(config.loginPath, request.url);
    loginUrl.searchParams.set('redirect', request.nextUrl.pathname);
    loginUrl.searchParams.set('error', errorType);
    loginUrl.searchParams.set('message', encodeURIComponent(errorMessage));

    // Clear the invalid token cookie
    const response = NextResponse.redirect(loginUrl);
    response.cookies.delete(config.tokenCookieName);

    return response;
  }
}

/**
 * Middleware Configuration
 * 
 * The matcher configuration follows Next.js best practices:
 * - Excludes static files and assets from middleware execution
 * - Excludes authentication-related API routes
 * - Applies middleware to all other routes for authentication checks
 * 
 * This improves performance by avoiding unnecessary middleware execution
 * on static assets and authentication endpoints.
 */
export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api/auth (authentication API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     * - sitemap.xml (sitemap file)
     * - robots.txt (robots file)
     * - manifest.json (PWA manifest file)
     */
    '/((?!api/auth|_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt|manifest.json).*)',
  ],
  // Optional: Specify runtime if needed (defaults to Edge Runtime)
  // runtime: 'nodejs',
};

// Export types for use in other files
export type { JWTPayload, MiddlewareConfig };

