import React, { useState } from 'react';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";

interface PostData {
  title: string;
  content: string;
}

export default function CreatePostPage() {
  const [postData, setPostData] = useState<PostData>({
    title: '',
    content: ''
  });

  // Check if both fields are filled to enable/disable the Publish button
  const isFormValid = postData.title.trim() !== '' && postData.content.trim() !== '';

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPostData(prev => ({
      ...prev,
      title: e.target.value
    }));
  };

  const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setPostData(prev => ({
      ...prev,
      content: e.target.value
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (isFormValid) {
      // Here you would typically send the data to your backend
      console.log('Publishing post:', postData);

      // You can also show a success message, reset the form, etc.
      alert('Post published successfully!');

      // Reset form after submission
      setPostData({
        title: '',
        content: ''
      });
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6 space-y-6">
      <div className="space-y-2">
        <h1 className="text-3xl font-bold tracking-tight">Create New Post</h1>
        <p className="text-muted-foreground">
          Fill in the title and content below to create a new post.
        </p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
          <Label htmlFor="title">Title</Label>
          <Input
            id="title"
            type="text"
            placeholder="Enter your post title..."
            value={postData.title}
            onChange={handleTitleChange}
            className="w-full"
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="content">Content</Label>
          <Textarea
            id="content"
            placeholder="Write your post content here..."
            value={postData.content}
            onChange={handleContentChange}
            className="min-h-[200px] w-full resize-none"
          />
        </div>

        <div className="flex justify-end pt-4">
          <Button
            type="submit"
            disabled={!isFormValid}
            className="min-w-[120px]"
          >
            Publish
          </Button>
        </div>
      </form>

      {/* Optional: Visual feedback for form validation */}
      <div className="text-sm text-muted-foreground border-t pt-4">
        <p>
          Status: {isFormValid ? 
            <span className="text-green-600">✓ Ready to publish</span> : 
            <span className="text-orange-600">⚠ Fill in both title and content</span>
          }
        </p>
      </div>
    </div>
  );
}

// Alternative version using React Hook Form for more complex validation scenarios
